<?php declare(strict_types=1); ?>
<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ana sayfa bölümleri</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f7f5;color:#20332c;font-family:Inter,system-ui,sans-serif}.wrap{max-width:1000px;margin:32px auto;padding:0 18px}.panel{background:#fff;border:1px solid #e4ebe6;border-radius:16px;padding:22px;margin:15px 0}.row{display:grid;grid-template-columns:1fr 1fr;gap:14px}label{display:block;font-size:13px;font-weight:750;margin:12px 0}input{display:block;width:100%;padding:11px;border:1px solid #dfe7e1;border-radius:9px;margin-top:6px;font:inherit}.actions{display:flex;justify-content:space-between;align-items:center;gap:12px}.btn{background:#167c80;color:#fff;border:0;border-radius:10px;padding:13px 20px;font-weight:800}.muted{color:#708078;font-size:13px}@media(max-width:650px){.row{grid-template-columns:1fr}}
/* Consistent admin links and actions */
a{color:#176b50;text-decoration:none;transition:color .18s ease,background-color .18s ease,border-color .18s ease}a:hover{color:#104c39;text-decoration:none}td a:not([class]),.table-wrap a:not([class]){display:inline-flex;align-items:center;justify-content:center;padding:7px 11px;border:1px solid #dce9e0;border-radius:8px;background:#f5faf6;color:#176b50;font-size:12px;font-weight:750;white-space:nowrap}td a:not([class]):hover,.table-wrap a:not([class]):hover{background:#eaf4ee;border-color:#b9d8c4}button,input[type=submit]{cursor:pointer;font:inherit}button{transition:filter .18s ease,transform .18s ease}button:hover,input[type=submit]:hover{filter:brightness(.96)}
</style></head><body><main class="wrap"><h1>Ana sayfa bölümleri</h1><p class="muted">Bölümleri açıp kapatabilir, sıralarını ve içeriklerini düzenleyebilirsiniz.</p><form method="post" action="/admin/homepage"><?= csrf_field() ?><?php foreach($sections as $section): ?><section class="panel"><div class="actions"><h2><?= e(ucfirst($section['section_key'])) ?></h2><label><input type="checkbox" name="sections[<?= e($section['section_key']) ?>][is_active]" value="1" <?= $section['is_active']?'checked':'' ?> style="display:inline;width:auto"> Yayında</label></div><div class="row"><label>Bölüm başlığı<input name="sections[<?= e($section['section_key']) ?>][title]" value="<?= e($section['title']) ?>"></label><label>Sıralama<input type="number" min="0" max="99" name="sections[<?= e($section['section_key']) ?>][sort_order]" value="<?= (int)$section['sort_order'] ?>"></label></div><label>Açıklama<input name="sections[<?= e($section['section_key']) ?>][subtitle]" value="<?= e($section['subtitle']) ?>"></label><?php if($section['section_key']==='hero'): ?><label>Karşılama görseli URL<input name="sections[<?= e($section['section_key']) ?>][image_url]" value="<?= e($section['image_url']) ?>" placeholder="https://..."></label><?php endif; ?></section><?php endforeach; ?><button class="btn">Değişiklikleri kaydet</button></form></main></body></html>